R=[]
def add(id,title,authors,year,status,venue,topics,methods,summary,ssrn=None,doi=None,urls=None,basis='Latest local résumé (21 November 2026); title and bibliographic listing only.',reviewed=False,question=None,findings=None,category=None):
 links=[{'label':label,'url':url} for label,url in (urls or [])]
 sources=[url for label,url in (urls or [])]
 if ssrn:
  u='https://papers.ssrn.com/sol3/papers.cfm?abstract_id='+str(ssrn)
  if not any(x['url']==u for x in links):links.append({'label':'SSRN','url':u})
  sources.append(u)
 if doi:
  u='https://doi.org/'+doi
  if not any(x['url']==u for x in links):links.append({'label':'DOI','url':u})
  sources.append(u)
 if not links:links=[{'label':'CV listing','url':CV}]
 if not sources:sources=[CV]
 d=dict(id=id,title=title,authors=authors,year=year,status=status,venue=venue,topics=topics,methods=methods,summary=summary,question=question,findings=findings or [],links=links,fullTextReviewed=reviewed,sourceBasis=basis,sourceUrls=list(dict.fromkeys(sources)))
 if ssrn:d['ssrnId']=str(ssrn)
 if doi:d['doi']=doi
 if category:d['category']=category
 R.append(d)
CC='Cantay Caliskan'
P='Politics & place'; A='AI & society'; N='Networks & behavior'; E='Environment'; G='Games & history'; M='Methods'
# Latest supplied manuscripts.
add('campus-sustainability','What street-level imagery can and cannot tell us about campus sustainability: a measurement study of 252 U.S. campuses',[CC,'Hari Acharya','Nyaradzo Mararanje','Albert Mejooli','Zhihan Zhang'],2026,'Working paper',None,[E,M],['Computer vision','Street-level imagery','Predictive modeling'], 'A measurement study links street-level and aerial imagery to 252 U.S. campuses and tests what visible conditions can reveal about sustainability ratings. Imagery captures features such as vegetation but explains only a limited share of institutional sustainability scores.',urls=[('Full paper','/papers/campus-sustainability.pdf')],basis='Supplied manuscript dated 30 October 2026; full text reviewed, including discussion and limitations. CV hyperlink for this title is misassigned and is not used.',reviewed=True,question='What can campus imagery credibly measure about sustainability?',findings=['Imagery explained at most about 10% of variation in STARS overall scores across evaluated models.','Vegetation measurements aligned across street-level and aerial imagery, with substantial seasonality.','The proposed Visible Campus Environment Index describes visible conditions rather than institutional sustainability performance.'])
add('resurrecting-theology','Resurrecting Theology: When Historical Scholars Confront the Modern World Through AI',[CC,'Mija Aleksandraviciute','Anna Fang'],2026,'Working paper',None,[A,M],['Large language models','Retrieval-augmented generation','Survey simulation'],'Six language models answer survey questions in the personas of 23 religious and intellectual figures. The study compares responses with and without retrieved texts and finds that model identity accounts for more variation than tradition and scholar combined.',ssrn='7733918',urls=[('Full paper','/papers/resurrecting-theology.pdf')],basis='Supplied November 2026 manuscript; abstract and full text reviewed by the PDF review agent. Supplied manuscript takes precedence over older conference descriptions.',reviewed=True,question='Whose views does an AI-generated historical persona express?',findings=['The study records 528,375 responses across six language models.','In the main WVS retrieval panel, model identity accounts for 37% of item-level variance, versus 17% for tradition and scholar together.','Retrieval separates personas but does not improve the tested historical contrasts.'])
add('partisan-visibility','The Address of the Party: Measuring Partisan Visibility in Turkey',[CC],2026,'Working paper',None,[P,M],['Spatial analysis','Street-level imagery','Human annotation'],'A directory of party organizations and annotated Street View panoramas is used to study where Turkish parties locate offices and display symbols. Offices cluster near commerce, government institutions, and rival parties; nearby symbol shares do not predict changes in electoral support.',ssrn='7733958',urls=[('Full paper','/papers/partisan-visibility.pdf')],basis='Supplied November 2026 manuscript; abstract and full-text review by the PDF review agent.',reviewed=True,question='Where do parties organize, and what do they make visible nearby?',findings=['The study examines 5,928 party organizations across 973 districts and 6,496 annotated panoramas.','In the directory, 72% of offices have a rival within 250 meters, compared with 30% under the comparison model.','The paper finds no evidence that symbol shares predict changes in electoral support.'])
add('judicial-voice','Who Speaks at the Court? Bench Roles, Language, and Judicial Voice at the European Court of Human Rights',['Ezgi Siir Kibris',CC],2026,'Working paper',None,[P,N,M],['Audio analysis','Speaker attribution','Hearing fixed effects'],'Recordings of 252 Grand Chamber hearings reveal substantial differences in judges’ participation in public questioning. National judges of respondent states ask questions more often, and documented language proficiency is also associated with participation.',urls=[('Full paper','/papers/judicial-voice.pdf')],basis='Supplied manuscript dated 22 November 2026; full-text review includes discussion and observational limitations. Kept distinct from Do Judges Have Emotions?, which has a different title and SSRN identifier.',reviewed=True,question='Which judges take the floor when every judge has an equal vote?',findings=['The data cover 140 judges, 4,254 sittings, and 2,106 question units.','On the same bench, the respondent state’s national judge is 23.1 percentage points more likely to ask a question.','The estimated gender difference is small and imprecise.'])
