add('party-positions','Using Generative AI to Calculate Party Positions: A Comparison of Human Experts and Large Language Models',[CC,'Junhua Huang','Yiyang Huang','Ruoxuan Lin','Wanting Shan'],2025,'Published','Journal of Political Institutions and Political Economy',[A,P,M],['Large language models','Manifesto analysis','Human-model comparison'],'Five language models estimate party positions from manifestos in Germany, the United Kingdom, and the United States. Comparison with expert coding reveals systematic moderation of the estimated positions of left- and right-leaning manifestos.',doi='10.1561/113.00000126',urls=[('Publisher','https://www.nowpublishers.com/article/Details/PIP-0126'),('Open manuscript','https://priceschool.usc.edu/wp-content/uploads/2024/12/Caliskan-et-al.pdf')],basis='Published status and year from latest CV; author order and reviewed full text from the publicly hosted USC manuscript dated 26 July 2024, not the final version of record.',reviewed=True,question='Can large language models replace experts in estimating party positions?',findings=['In the reviewed manuscript, model-estimated positions are less extreme on average than the expert benchmark.'])
add('veiled-metrics','Measuring political polarization through visible interactions between religious and non-religious citizens',[CC,'Liangze Ke','Yichen Li','Yuka Shimazaki','Muchen Zhong'],2025,'Published','Scientific Reports',[P,N,M],['Computer vision','Object detection','Distance estimation'],'Computer vision and street videos from Turkey are used to estimate distances between pedestrians with different visible identities. The article develops a behavioral proxy for studying polarization while emphasizing the interpretation of visible interactions.',ssrn='4907046',doi='10.1038/s41598-025-01307-5',urls=[('Full article','https://www.nature.com/articles/s41598-025-01307-5'),('Publisher PDF','https://www.nature.com/articles/s41598-025-01307-5.pdf')],basis='Publisher PDF downloaded and reviewed; official title and author order from the version of record. CV and SSRN use the earlier Veiled Metrics title.',reviewed=True,question='What can physical proximity in public space reveal about social divisions?',findings=['The study analyzes more than 1,400 publicly available street videos and approximately 170,000 frames.','Distance patterns vary with visible gender and religious identity; visible markers and spatial proximity are proxies, not direct measures of private beliefs.'])
add('dynamic-networks-sgd','Stochastic Gradient Descent-based Inference for Dynamic Network Models with Attractors',['Hancong Pan','Xiaojing Zhu',CC,'Dino P. Christenson','Konstantinos Spiliopoulos','Dylan Walker','Eric D. Kolaczyk'],2025,'Published','Journal of Computational and Graphical Statistics',[N,M],['Dynamic network models','Stochastic gradient descent','Uncertainty quantification'],'A stochastic gradient descent approach makes coevolving latent space network models more scalable and allows actors to join or leave over time. Simulations and an application to congressional social-media networks illustrate the method.',doi='10.1080/10618600.2024.2447478',urls=[('Open manuscript','https://arxiv.org/abs/2403.07124'),('Author-hosted article','https://dinopc.org/papers/clsnagradient.pdf')],basis='Full published article on coauthor website downloaded and reviewed; publisher DOI and 2025 year match CV.',reviewed=True,question='How can dynamic network models scale while tracking changing membership?',findings=['Simulations show improved scalability with little loss of accuracy relative to the compared MCMC estimation.'])
add('threat-vocalisations','Threat Vocalisations are Acoustically Similar between Humans (Homo sapiens) and Chimpanzees (Pan troglodytes)',['Roza G. Kamiloğlu','Cantay Çalışkan','Katie E. Slocombe','Disa A. Sauter'],2023,'Published','Bioacoustics',[N,M],['Acoustic analysis','Unsupervised learning'],'The study compares human and chimpanzee vocalizations across ten equivalent behavioral contexts using acoustic distance and separability measures.',doi='10.1080/09524622.2023.2250320',urls=[('Publisher','https://www.tandfonline.com/doi/full/10.1080/09524622.2023.2250320'),('Open article','https://pure.uva.nl/ws/files/191322469/Threat_vocalisations_are_acoustically_similar_between_humans_Homo_sapiens_and_chimpanzees_Pan_troglodytes_.pdf')],basis='Full published article downloaded from the University of Amsterdam repository and reviewed, including discussion and limitations.',reviewed=True,findings=['Threat vocalizations are acoustically distinctive from other contexts and similar across the two species.'])
add('positive-negative-partisanship','Disentangling positive and negative partisanship in social media interactions using a coevolving latent space network with attractors model',['Xiaojing Zhu',CC,'Dino P. Christenson','Konstantinos Spiliopoulos','Dylan Walker','Eric D. Kolaczyk'],2023,'Published','Journal of the Royal Statistical Society: Series A',[N,M],['Latent space models','Bayesian inference','Social network analysis'],'A coevolving latent space model separates attraction within parties from repulsion across parties in Twitter and Reddit networks. The application explores how the balance of these forces changes over time.',doi='10.1093/jrsssa/qnad008',urls=[('Publisher','https://academic.oup.com/jrsssa/advance-article-abstract/doi/10.1093/jrsssa/qnad008/7058002'),('Open manuscript','https://arxiv.org/abs/2109.13129'),('Code and data','https://github.com/KolaczykResearch/CLSNA-2Party-Polarization')],basis='Full author-hosted manuscript reviewed at https://dinopc.org/papers/coevolvinglatent.pdf; arXiv and publisher establish author order, which differs from the CV listing. Findings depend in part on network construction.',reviewed=True,question='How do in-group attraction and out-group repulsion shape partisan networks?')
add('varieties-corona-news','Varieties of corona news: a cross-national study on the foundations of online misinformation production during the COVID-19 pandemic',[CC,'Alaz Kilicaslan'],2022,'Published','Journal of Computational Social Science',[A,N,M],['Text similarity','Clustering','Network distances'],'A cross-national analysis examines 10,131 pieces of COVID-19 misinformation using text, network, and statistical methods. It studies how content patterns relate to country characteristics.',doi='10.1007/s42001-022-00193-5',ssrn='4021264',urls=[('Publisher','https://link.springer.com/article/10.1007/s42001-022-00193-5'),('Full article','https://link.springer.com/content/pdf/10.1007/s42001-022-00193-5.pdf')],basis='Full publisher PDF downloaded and reviewed, including methods and discussion. Uses first-online year 2022 as in CV; print volume is 2023.',reviewed=True,findings=['Country-level factors have limited overall predictive support; common content is more evident where press freedom and human development are low.'])
